<?php
namespace App\Filament\Resources;use App\Enums\OrderStatus;use App\Filament\Resources\OrderResource\Pages;use App\Models\Order;use App\Models\User;use App\Services\DeliveryService;use Filament\Forms;use Filament\Forms\Form;use Filament\Resources\Resource;use Filament\Tables;use Filament\Tables\Table;
class OrderResource extends Resource {protected static ?string $model=Order::class;protected static ?string $navigationIcon='heroicon-o-truck';protected static ?string $navigationLabel='سفارش‌ها';public static function form(Form $form):Form{return $form->schema([Forms\Components\TextInput::make('order_number')->required()->unique(ignoreRecord:true),Forms\Components\Select::make('customer_id')->relationship('customer','name')->searchable()->required(),Forms\Components\Select::make('visitor_id')->options(User::role(['Visitor','Driver'])->pluck('name','id'))->searchable(),Forms\Components\DatePicker::make('delivery_date'),Forms\Components\TextInput::make('total_weight')->numeric()->required(),Forms\Components\TextInput::make('total_amount')->numeric()->required(),Forms\Components\Select::make('status')->options(collect(OrderStatus::cases())->mapWithKeys(fn($s)=>[$s->value=>$s->label()]))->required(),Forms\Components\Textarea::make('notes')->columnSpanFull()])->columns(2);}public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('order_number')->searchable(),Tables\Columns\TextColumn::make('customer.name')->label('مشتری')->searchable(),Tables\Columns\TextColumn::make('customer.mobile')->label('موبایل')->searchable(),Tables\Columns\TextColumn::make('visitor.name')->label('ویزیتور'),Tables\Columns\TextColumn::make('total_amount')->money('IRR')->label('مبلغ'),Tables\Columns\TextColumn::make('status')->badge(),Tables\Columns\TextColumn::make('delivery_date')->date()])->actions([Tables\Actions\EditAction::make(),Tables\Actions\Action::make('issue_code')->label('صدور / ارسال کد')->requiresConfirmation()->action(fn(Order $record)=>app(DeliveryService::class)->issueCode($record->load('customer')))] )->defaultSort('delivery_date','desc');}public static function getPages():array{return ['index'=>Pages\ListOrders::route('/'),'create'=>Pages\CreateOrder::route('/create'),'edit'=>Pages\EditOrder::route('/{record}/edit')];}}
